"""Embedded official CFTC TFF weekly positions for ES/NQ (2010 onward).

Generated from CFTC Socrata dataset gpe5-46if. Values are net positions divided
by open interest, quantized to 1 basis point solely to fit QuantConnect's free
project file limits. Dates are report dates (Tuesday); the research algorithm
applies the +3 calendar-day publication lag.
"""

import base64
import struct
import zlib
from datetime import date

_ES_B64 = """"""
_NQ_B64 = """"""


def load_tff_rows():
    base_date = date(2010, 1, 1)
    grouped = {}
    for code, payload in (("13874+", _ES_B64), ("20974+", _NQ_B64)):
        raw = zlib.decompress(base64.b64decode(payload))
        rows = []
        for offset in range(0, len(raw), 10):
            day, dealer, asset_mgr, lev_money, nonrept = struct.unpack_from(
                "<Hhhhh", raw, offset
            )
            rows.append({
                "report_date": base_date.fromordinal(base_date.toordinal() + day),
                "dealer": dealer / 10_000.0,
                "asset_mgr": asset_mgr / 10_000.0,
                "lev_money": lev_money / 10_000.0,
                "nonrept": nonrept / 10_000.0,
            })
        grouped[code] = rows
    return grouped
